[ExtensionOf(formStr(UnitOfMeasureConversionEditOrCreate))]
internal final class NDXUnitOfMeasureConversionEditOrCreate_frm_Extension
{
}

Method.Source:
/// <summary>
/// hide NDX controls
/// </summary>
void hideNDXcontrols()
{
    UnitOfMeasureConversion_NDXUnitLevel.visible(false);
    NDXLimit.visible(false);
    NDXWeight.visible(false);
    NDXDimensions.visible(false);
    NDXDeliveryOptions.visible(false);
}

/// <summary>
/// init chain of command
/// </summary>
void init()
{
    UnitOfMeasureConversionType conversionType;

    next init();

    if(this.args().parmEnumType() == enumNum(UnitOfMeasureConversionType))
    {
        conversionType = this.args().parmEnum();
        if(conversionType == UnitOfMeasureConversionType::Standard)
        {
            this.hideNDXControls();
        }
    }
}
